from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
old='''<section id="login" class="card auth"><h2>Entrar no CRM</h2><p class="muted">Entre com o usuário criado em Authentication → Users no Supabase.</p><form id="loginForm"><label>E-mail</label><input id="email" type="email" required autocomplete="username"><label>Senha</label><input id="password" type="password" required autocomplete="current-password"><div class="formactions"><button>Entrar</button></div></form><p class="muted">Seu acesso é individual. Não compartilhe sua senha.</p></section>'''
new='''<section id="login" class="auth login-shell"><div class="login-panel"><div class="login-brand"><div class="login-logos"><img src="https://raw.githubusercontent.com/costathiagocs-web/crm-comercial-pessoal/desenvolvimento-3.4-melhorias/assets/logo-eletro.webp" alt="Eletro Quadros"><span>+</span><img src="https://raw.githubusercontent.com/costathiagocs-web/crm-comercial-pessoal/desenvolvimento-3.4-melhorias/assets/logo-stampo.webp" alt="Stampo Metalúrgica"></div><h2>Acesse sua conta</h2><p>CRM Comercial 3.4 • Gestão multiempresa</p></div><form id="loginForm" class="login-form"><label for="email">Usuário</label><div class="login-field"><span class="login-icon" aria-hidden="true">◉</span><input id="email" type="email" required autocomplete="username" placeholder="seuemail@empresa.com"></div><label for="password">Senha</label><div class="login-field"><span class="login-icon" aria-hidden="true">▣</span><input id="password" type="password" required autocomplete="current-password" placeholder="Digite sua senha"><button type="button" id="togglePassword" class="password-toggle" aria-label="Mostrar senha">👁</button></div><button id="loginButton" class="login-submit">Entrar</button><button type="button" id="forgotPassword" class="login-link">Esqueceu sua senha?</button></form><p class="login-note">Use seu acesso individual. Não compartilhe sua senha.</p></div></section>'''
if old not in s: raise SystemExit('login antigo não encontrado')
s=s.replace(old,new,1)
css='''\n/* CRM 3.4 • login profissional */\n.login-shell{max-width:none!important;margin:0!important;padding:34px 18px!important;min-height:calc(100vh - 110px);display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at 50% 30%,#174f94 0,#0f3568 36%,#091d38 100%);border:0!important;border-radius:0!important;box-shadow:none!important}.login-panel{width:min(100%,460px);background:#f8fbff;border:1px solid #d8e5f5;border-radius:28px;padding:34px 38px 28px;box-shadow:0 26px 70px #0007;color:#122844}.login-brand{text-align:center;margin-bottom:24px}.login-brand h2{margin:12px 0 4px!important;color:#173f7a!important;font-size:28px}.login-brand p{margin:0;color:#6f8199;font-size:13px}.login-logos{display:flex;align-items:center;justify-content:center;gap:12px;min-height:58px}.login-logos img{max-height:52px;max-width:150px;object-fit:contain;border-radius:8px}.login-logos span{font-weight:900;color:#f5a12a;font-size:22px}.login-form label{color:#243a57;margin:14px 0 6px}.login-field{display:flex;align-items:center;border:2px solid #c7d7ec;background:#fff;border-radius:12px;overflow:hidden;transition:.15s ease}.login-field:focus-within{border-color:#225da8;box-shadow:0 0 0 4px #225da81c}.login-field input{border:0!important;box-shadow:none!important;background:transparent!important;color:#17283d!important;min-height:48px}.login-icon{width:44px;text-align:center;color:#58708f;font-size:17px}.password-toggle{width:48px;height:48px;padding:0!important;border:0!important;background:transparent!important;color:#4e6480!important;box-shadow:none!important;transform:none!important;filter:none!important}.login-submit{width:100%;margin-top:18px;min-height:50px;border-radius:10px;background:linear-gradient(180deg,#245edb,#173fbd)!important;font-size:16px}.login-link{width:100%;margin-top:8px;background:transparent!important;color:#2458c7!important;border:0!important;box-shadow:none!important;font-weight:650}.login-note{text-align:center;color:#7b899b;font-size:12px;margin:16px 0 0}.login-submit[disabled]{opacity:.65;cursor:wait}@media(max-width:600px){.login-shell{padding:20px 12px!important}.login-panel{padding:28px 20px 22px;border-radius:22px}.login-logos{gap:8px}.login-logos img{max-width:122px;max-height:45px}.login-brand h2{font-size:24px!important}}\n'''
if 'CRM 3.4 • login profissional' not in s:
    s=s.replace('</style>',css+'</style>',1)
oldjs="$('loginForm').onsubmit=async e=>{e.preventDefault();const {error}=await sb.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value});if(error)message('Não foi possível entrar: '+error.message,true);else{message('Login realizado');await boot()}};"
newjs="$('loginForm').onsubmit=async e=>{e.preventDefault();const btn=$('loginButton');btn.disabled=true;btn.textContent='Entrando...';const {error}=await sb.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value});btn.disabled=false;btn.textContent='Entrar';if(error)message('Usuário ou senha inválidos. Verifique os dados e tente novamente.',true);else{message('Login realizado');await boot()}};\n$('togglePassword').onclick=()=>{const p=$('password'),show=p.type==='password';p.type=show?'text':'password';$('togglePassword').setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha')};\n$('forgotPassword').onclick=async()=>{const email=$('email').value.trim();if(!email){message('Informe seu usuário (e-mail) para recuperar a senha.',true);return}const {error}=await sb.auth.resetPasswordForEmail(email);message(error?'Não foi possível iniciar a recuperação: '+error.message:'Enviamos as instruções de recuperação para o e-mail informado.',!!error)};"
if oldjs not in s: raise SystemExit('handler de login não encontrado')
s=s.replace(oldjs,newjs,1)
p.write_text(s,encoding='utf-8')
# trigger
